test("default Leaderboard uses an independent host Top-N plan and original sole active producer",()=>{const m=sourceModule();m.widgets.rank={id:"rank",name:"Top exposure",type:"Leaderboard",config:{objectSetVarId:"notes",property:"revenueImpact",limit:8,activeVarId:"selected"}};m.sections.root.children[0]={kind:"widget",id:"rank"};const mapped={...bindings,fields:{Asset:{...bindings.fields.Asset,revenueImpact:"qty"}},leaderboards:{rank:{labelField:"note"}}},typed={...target,entities:[{...target.entities[0],fields:[...target.entities[0].fields,{name:"qty",type:"decimal"}]}]},source=JSON.stringify(m),r=compileWorkshopModule(source,"page",mapped,typed);assert.ok(r.draft,JSON.stringify(r.diagnostics));const rank=r.draft.sections.find(s=>s.widget==="record-leaderboard"),q=r.draft.document.queries[r.draft.document.variables[rank.collectionVariable].source.query],detail=r.draft.sections.find(s=>s.widget==="detail");assert.deepEqual(rank.leaderboard,{valueField:"qty",labelField:"note",limit:8,ascending:false});assert.deepEqual(q.sort,["-qty","id"]);assert.equal(q.limit,8);assert.equal(q.offset,0);assert.equal(r.draft.document.variables[detail.recordVariable].source.section,rank.id);assert.equal(r.source,source);assert.equal(compileWorkshopModule(source,"page",bindings,typed).draft,undefined);assert.equal(compileWorkshopModule(source,"page",mapped,{...typed,profile:"platform.page.v2.50"}).draft,undefined);m.widgets.rank.config.ascending=true;const asc=compileWorkshopModule(JSON.stringify(m),"page",mapped,typed);assert.ok(asc.draft);assert.deepEqual(Object.values(asc.draft.document.queries).find(q=>q.sort?.[0]==="qty").sort,["qty","id"]);m.sections.root.children.push({kind:"widget",id:"table"});assert.equal(compileWorkshopModule(JSON.stringify(m),"page",mapped,typed).draft,undefined);});
test("SummaryStats maps the original numeric field to one scoped five-measure source and rejects lossy configurations",()=>{const m=sourceModule();m.widgets.summary={id:"summary",name:"Pressure stats",type:"SummaryStats",config:{objectSetVarId:"notes",property:"pressure"}};m.sections.root.children.push({kind:"widget",id:"summary"});const mapped={...bindings,fields:{Asset:{...bindings.fields.Asset,pressure:"qty"}}},typed={...target,entities:[{...target.entities[0],fields:[...target.entities[0].fields,{name:"qty",type:"decimal"}]}]},source=JSON.stringify(m),r=compileWorkshopModule(source,"page",mapped,typed);assert.ok(r.draft,JSON.stringify(r.diagnostics));const section=r.draft.sections.find(s=>s.widget==="summary-stats"),set=r.draft.document.variables[section.collectionVariable],stats=r.draft.document.variables[section.statisticsVariable];assert.equal(section.summaryField,"qty");assert.equal(stats.type,"statistics");assert.deepEqual(stats.source,{kind:"statistics",query:set.source.query,measure:"qty"});assert.equal(r.source,source);assert.equal(compileWorkshopModule(source,"page",bindings,typed).draft,undefined);assert.equal(compileWorkshopModule(source,"page",mapped,{...typed,profile:"platform.page.v2.49"}).draft,undefined);m.widgets.summary.config.function="summarize()";assert.equal(compileWorkshopModule(JSON.stringify(m),"page",mapped,typed).draft,undefined);});
test("default Gauge maps original average field and freezes numeric precision, display maximum, suffix and threshold",()=>{const m=sourceModule();m.variables.push({id:"avgAvailability",name:"Average availability",type:"numeric",definitionKind:"objectSetAggregation",inputVarId:"notes",transformations:[{op:"aggregate",args:{by:"avgAvailability"}}]});m.widgets.gauge={id:"gauge",name:"Fleet gauge",type:"Gauge",config:{variableId:"avgAvailability",label:"Fleet availability",max:100,suffix:"%",warnAt:60}};m.sections.root.children.push({kind:"widget",id:"gauge"});const mapped={...bindings,aggregates:{avgAvailability:{measure:"avg:availability"}}},typed={...target,entities:[{...target.entities[0],fields:[...target.entities[0].fields,{name:"availability",type:"decimal"}]}]},source=JSON.stringify(m),r=compileWorkshopModule(source,"page",mapped,typed);assert.ok(r.draft,JSON.stringify(r.diagnostics));const gauge=r.draft.sections.find(s=>s.widget==="gauge"),v=r.draft.document.variables[gauge.gaugeValueVariable];assert.equal(v.type,"number");assert.equal(v.mode,"aggregate");assert.equal(v.source.measure,"avg:availability");assert.deepEqual(gauge.gauge,{max:100,warnAt:60,label:"Fleet availability",suffix:"%"});assert.equal(r.source,source);assert.equal(compileWorkshopModule(source,"page",bindings,typed).draft,undefined);assert.equal(compileWorkshopModule(source,"page",mapped,{...typed,profile:"platform.page.v2.48"}).draft,undefined);for(const change of [c=>c.max=0,c=>c.warnAt="60",c=>c.script="predict()"]){const copy=structuredClone(m);change(copy.widgets.gauge.config);assert.equal(compileWorkshopModule(JSON.stringify(copy),"page",mapped,typed).draft,undefined);}const fn=structuredClone(m);fn.variables.find(v=>v.id==="avgAvailability").definitionKind="function";assert.equal(compileWorkshopModule(JSON.stringify(fn),"page",mapped,typed).draft,undefined);});
test("ProgressBar binds original complete counts and both denominators while numeric inputs share their original text state",()=>{
 const m=sourceModule();m.variables.push({id:"count",name:"Complete count",type:"numeric",definitionKind:"variableTransformation",inputVarId:"notes",transformations:[{op:"cardinality"}]},{id:"total",name:"Total input",type:"numeric",definitionKind:"static",staticValue:400});m.widgets.progress={id:"progress",name:"Open work",type:"ProgressBar",config:{valueVarId:"count",total:400,label:"Open work orders"}};m.widgets.totalInput={id:"totalInput",name:"Total",type:"NumericInput",config:{variableId:"total",label:"Total"}};m.widgets.dual={id:"dual",name:"Input denominator",type:"ProgressBar",config:{valueVarId:"count",totalVarId:"total"}};m.sections.root.children.push(...["progress","dual","totalInput"].map(id=>({kind:"widget",id})));const source=JSON.stringify(m),r=compileWorkshopModule(source,"page",bindings,target);assert.ok(r.draft,JSON.stringify(r.diagnostics));const p=r.draft.sections.find(s=>s.title==="Open work"),dual=r.draft.sections.find(s=>s.title==="Input denominator"),count=r.draft.document.variables[p.progressValueVariable],total=r.draft.document.variables[dual.progressTotalVariable];assert.equal(count.mode,"aggregate");assert.equal(count.source.kind,"count");assert.equal(p.progressTotal,"400");assert.equal(p.progressLabel,"Open work orders");assert.equal(dual.progressValueVariable,p.progressValueVariable);assert.equal(total.expression.op,"parse-decimal");const input=r.draft.sections.find(s=>s.title==="Total"),inputNode=Object.values(r.draft.document.nodes).find(n=>n.section===input.id);assert.equal(total.expression.args[0].variable,inputNode.valueVariable);assert.equal(r.source,source);assert.equal(compileWorkshopModule(source,"page",bindings,{...target,profile:"platform.page.v2.47"}).draft,undefined);
 for(const change of [c=>c.total=0,c=>c.total=-1,c=>c.total="400",c=>c.totalVarId="total",c=>c.valueVarId="notes",c=>c.script="execute()"]){const copy=structuredClone(m);change(copy.widgets.progress.config);assert.equal(compileWorkshopModule(JSON.stringify(copy),"page",bindings,target).draft,undefined);}
});
test("ProgressBar explicit filtered count uses the original query conditions and refuses unsupported aggregate scalars",()=>{const m=sourceModule();m.variables.push({id:"count",name:"Named count",type:"numeric",definitionKind:"objectSetAggregation",inputVarId:"notes",transformations:[{op:"aggregate",args:{by:"countActive"}}]});m.widgets.progress={id:"progress",name:"Active share",type:"ProgressBar",config:{valueVarId:"count"}};m.sections.root.children.push({kind:"widget",id:"progress"});const typed={...target,entities:[{...target.entities[0],fields:[...target.entities[0].fields,{name:"status",type:"choice",choices:["open","done"]}]}]},mapped={...bindings,aggregates:{count:{measure:"count",conditions:[{field:"status",op:"=",value:{literal:"open"}}]}}},r=compileWorkshopModule(JSON.stringify(m),"page",mapped,typed);assert.ok(r.draft,JSON.stringify(r.diagnostics));const p=r.draft.sections.find(s=>s.widget==="progress"),count=r.draft.document.variables[p.progressValueVariable];assert.equal(p.progressTotal,"100");assert.deepEqual(r.draft.document.queries[count.source.query].conditions,[{field:"status",op:"=",value:{literal:"open"}}]);assert.equal(compileWorkshopModule(JSON.stringify(m),"page",bindings,typed).draft,undefined);assert.equal(compileWorkshopModule(JSON.stringify(m),"page",{...mapped,aggregates:{count:{measure:"sum:status"}}},typed).draft,undefined);});
test("default Gantt imports explicit original mixed time fields, fixed range and status tones without losing unsupported settings",()=>{
 const m=sourceModule();m.widgets.gantt={id:"gantt",name:"Work Order Schedule",type:"Gantt",config:{objectSetVarId:"notes"}};m.sections.root.children.push({kind:"widget",id:"gantt"});const fields={startField:"begin",endField:"due",titleField:"note",statusField:"status",rangeStart:"2026-09-01",rangeEnd:"2026-11-01",tones:[{value:"done",tone:"success"}]},mapped={...bindings,gantts:{gantt:fields}},typed={...target,entities:[{...target.entities[0],fields:[...target.entities[0].fields,{name:"begin",type:"datetime"},{name:"due",type:"date"},{name:"status",type:"choice",choices:["open","done"]}]}]},source=JSON.stringify(m),r=compileWorkshopModule(source,"page",mapped,typed);assert.ok(r.draft,JSON.stringify(r.diagnostics));const gantt=r.draft.sections.find(s=>s.widget==="record-gantt");assert.deepEqual(gantt.recordGantt,fields);assert.deepEqual(r.draft.document.queries[r.draft.document.variables[gantt.collectionVariable].source.query].sort,["id"]);assert.equal(r.source,source);assert.ok(r.diagnostics.some(d=>d.code==="native-gantt-window"&&!d.blocking));assert.equal(compileWorkshopModule(source,"page",bindings,typed).draft,undefined);assert.equal(compileWorkshopModule(source,"page",mapped,{...typed,profile:"platform.page.v2.46"}).draft,undefined);
 for(const change of [f=>f.startField="created",f=>f.endField="note",f=>f.statusField="note",f=>f.rangeStart="0000-01-01",f=>f.rangeEnd="2026-02-30",f=>f.rangeStart=f.rangeEnd,f=>f.tones=[{value:"unknown",tone:"warning"}],f=>f.tones=[{value:"done",tone:"red"}],f=>f.tones.push(f.tones[0])]){const f=structuredClone(fields);change(f);assert.equal(compileWorkshopModule(source,"page",{...mapped,gantts:{gantt:f}},typed).draft,undefined);}m.widgets.gantt.config.dragSchedule=true;assert.equal(compileWorkshopModule(JSON.stringify(m),"page",mapped,typed).draft,undefined);
});
test("source Calendar maps original business date and sole selection producer and refuses incomplete or conflicting declarations",()=>{const m=sourceModule();m.widgets.calendar={id:"calendar",name:"Work order calendar",type:"Calendar",config:{objectSetVarId:"notes",dateProperty:"due",activeVarId:"selected"}};m.sections.root.children[0]={kind:"widget",id:"calendar"};const mapped={...bindings,fields:{Asset:{...bindings.fields.Asset,due:"date"}},calendars:{calendar:{labelField:"note",initialMonth:"2026-10"}}},typed={...target,entities:[{...target.entities[0],fields:[...target.entities[0].fields,{name:"date",type:"date"}]}]},source=JSON.stringify(m),r=compileWorkshopModule(source,"page",mapped,typed);assert.ok(r.draft,JSON.stringify(r.diagnostics));const calendar=r.draft.sections.find(s=>s.widget==="record-calendar"),detail=r.draft.sections.find(s=>s.widget==="detail");assert.deepEqual(calendar.recordCalendar,{dateField:"date",labelField:"note",initialMonth:"2026-10"});assert.equal(r.draft.document.variables[detail.recordVariable].source.section,calendar.id);assert.deepEqual(r.draft.document.queries[r.draft.document.variables[calendar.collectionVariable].source.query].sort,["id"]);assert.equal(r.source,source);assert.equal(compileWorkshopModule(source,"page",bindings,typed).draft,undefined);assert.equal(compileWorkshopModule(source,"page",mapped,{...typed,profile:"platform.page.v2.45"}).draft,undefined);m.sections.root.children.push({kind:"widget",id:"table"});assert.equal(compileWorkshopModule(JSON.stringify(m),"page",mapped,typed).draft,undefined);});
