 const m=sourceModule();m.widgets.events={id:"events",name:"Alert Timeline",type:"Timeline",config:{objectSetVarId:"notes"}};m.sections.root.children.push({kind:"widget",id:"events"});const fields={timeField:"raised",titleField:"note",severityField:"severity",tones:[{value:"high",tone:"danger"}]},mapped={...bindings,events:{events:fields}},typed={...target,entities:[{...target.entities[0],fields:[...target.entities[0].fields,{name:"raised",type:"datetime"},{name:"severity",type:"choice",choices:["high","low"]}]}]},source=JSON.stringify(m),r=compileWorkshopModule(source,"page",mapped,typed);assert.ok(r.draft,JSON.stringify(r.diagnostics));const events=r.draft.sections.find(s=>s.widget==="record-events");assert.deepEqual(events.recordEvents,fields);assert.deepEqual(r.draft.document.queries[r.draft.document.variables[events.collectionVariable].source.query].sort,["id"]);assert.equal(r.source,source);assert.ok(r.diagnostics.some(d=>d.code==="native-event-window"&&!d.blocking));assert.equal(compileWorkshopModule(source,"page",bindings,typed).draft,undefined);assert.equal(compileWorkshopModule(source,"page",mapped,{...typed,profile:"platform.page.v2.44"}).draft,undefined);for(const change of [f=>f.timeField="created",f=>f.severityField="note",f=>f.tones=[{value:"unknown",tone:"danger"}],f=>f.tones=[{value:"high",tone:"red"}],f=>f.tones.push(f.tones[0])]){const f=structuredClone(fields);change(f);assert.equal(compileWorkshopModule(source,"page",{...mapped,events:{events:f}},typed).draft,undefined);}
