test("default board maps original lifecycle moves and the sole active producer without importing source action execution",()=>{
 const m=sourceModule();m.widgets.board={id:"board",name:"Asset status board",type:"KanbanBoard",config:{objectSetVarId:"notes",groupBy:"status",actionId:"updateAssetStatus",actionParam:"status",activeVarId:"selected"}};m.sections.root.children[0]={kind:"widget",id:"board"};const mapped={...bindings,fields:{Asset:{...bindings.fields.Asset,status:"state"}},boards:{board:{label:"note",fields:[],moves:["sample.note.close"]}}},typed={...target,entities:[{...target.entities[0],fields:[...target.entities[0].fields,{name:"state",type:"choice"}],lifecycle:{field:"state",initial:"open",states:[{name:"open",title:"Open"},{name:"done",title:"Done"}],transitions:[{schema:"sample.note.close",title:"Complete",from:["open"],to:["done"]}]}}]},source=JSON.stringify(m),r=compileWorkshopModule(source,"page",mapped,typed);assert.ok(r.draft,JSON.stringify(r.diagnostics));const board=r.draft.sections.find(s=>s.widget==="kanban"),detail=r.draft.sections.find(s=>s.widget==="detail");assert.equal(board.cardLabel,"note");assert.deepEqual(board.actions,["sample.note.close"]);assert.equal(r.draft.document.variables[detail.recordVariable].source.section,board.id);assert.ok(board.selection);assert.equal(r.source,source);assert.ok(r.diagnostics.some(d=>d.code==="native-board-moves"&&!d.blocking));
 const empty={...mapped,boards:{board:{...mapped.boards.board,moves:[]}}};assert.equal(compileWorkshopModule(source,"page",empty,typed).draft,undefined);const wrong={...mapped,boards:{board:{...mapped.boards.board,moves:["unknown"]}}};assert.equal(compileWorkshopModule(source,"page",wrong,typed).draft,undefined);m.sections.root.children.push({kind:"widget",id:"table"});assert.equal(compileWorkshopModule(JSON.stringify(m),"page",mapped,typed).draft,undefined);m.sections.root.children.pop();delete m.widgets.board.config.actionId;delete m.widgets.board.config.actionParam;assert.ok(compileWorkshopModule(JSON.stringify(m),"page",empty,typed).draft);assert.equal(compileWorkshopModule(JSON.stringify(m),"page",mapped,typed).draft,undefined);assert.equal(compileWorkshopModule(source,"page",mapped,{...typed,profile:"platform.page.v2.25"}).draft,undefined);
});
test("default PivotTable maps two distinct original axes and count without copying a client-side matrix",()=>{
 const m=sourceModule();m.widgets.pivot={id:"pivot",name:"Status × Priority",type:"PivotTable",config:{objectSetVarId:"notes",rows:"status",cols:"priority",measure:"count"}};m.sections.root.children.push({kind:"widget",id:"pivot"});const mapped={...bindings,fields:{Asset:{...bindings.fields.Asset,status:"stage",priority:"priority"}}},typed={...target,entities:[{...target.entities[0],fields:[...target.entities[0].fields,{name:"stage",type:"choice"},{name:"priority",type:"integer"}]}]},source=JSON.stringify(m),r=compileWorkshopModule(source,"page",mapped,typed);assert.ok(r.draft,JSON.stringify(r.diagnostics));const pivot=r.draft.sections.find(s=>s.widget==="pivot"),table=r.draft.sections.find(s=>s.widget==="table");assert.equal(pivot.group,"stage");assert.equal(pivot.columnGroup,"priority");assert.equal(pivot.measure,"count");assert.equal(pivot.collectionVariable,table.collectionVariable);assert.equal(r.source,source);assert.ok(r.diagnostics.some(d=>d.code==="native-pivot-count"&&!d.blocking));
 for(const change of [m=>m.widgets.pivot.config.cols="status",m=>m.widgets.pivot.config.measure="sum:qty",m=>m.widgets.pivot.config.rows="id",m=>m.widgets.pivot.config.script="run()",m=>delete m.widgets.pivot.config.cols]){const copy=structuredClone(m);change(copy);assert.equal(compileWorkshopModule(JSON.stringify(copy),"page",mapped,typed).draft,undefined);}assert.equal(compileWorkshopModule(source,"page",mapped,{...typed,profile:"platform.page.v2.22"}).draft,undefined);const hidden=structuredClone(typed.entities[0]);hidden.fields=hidden.fields.filter(f=>f.name!=="priority");assert.equal(compileWorkshopModule(source,"page",mapped,{...typed,entities:[hidden]}).draft,undefined);
});
test("default pie and donut map categorical fields to original complete counts and reject unsupported source settings",()=>{
 const m=sourceModule();m.widgets.pie={id:"pie",name:"Status Distribution",type:"ChartPie",config:{objectSetVarId:"notes",groupBy:"status"}};m.widgets.donut={id:"donut",name:"Priority Breakdown",type:"ChartPie",config:{objectSetVarId:"notes",groupBy:"priority",variant:"donut"}};m.sections.root.children.push({kind:"widget",id:"pie"},{kind:"widget",id:"donut"});const mapped={...bindings,fields:{Asset:{...bindings.fields.Asset,status:"stage",priority:"priority"}}},typed={...target,entities:[{...target.entities[0],fields:[...target.entities[0].fields,{name:"stage",type:"choice"},{name:"priority",type:"integer"}]}]},source=JSON.stringify(m),r=compileWorkshopModule(source,"page",mapped,typed);assert.ok(r.draft,JSON.stringify(r.diagnostics));const charts=r.draft.sections.filter(s=>s.widget==="chart");assert.deepEqual(charts.map(s=>[s.mark,s.group,s.measure,s.chartVariant]),[["arc","stage","count","pie"],["arc","priority","count","donut"]]);assert.equal(charts[0].collectionVariable,charts[1].collectionVariable);assert.equal(r.source,source);assert.ok(r.diagnostics.some(d=>d.code==="native-pie-count"&&!d.blocking));
 for(const change of [m=>m.widgets.pie.config.variant="3d",m=>m.widgets.pie.config.groupBy="id",m=>m.widgets.pie.config.measure="avg:qty",m=>m.widgets.pie.config.script="run()"]) {const copy=structuredClone(m);change(copy);assert.equal(compileWorkshopModule(JSON.stringify(copy),"page",mapped,typed).draft,undefined);}assert.equal(compileWorkshopModule(source,"page",mapped,{...typed,profile:"platform.page.v2.43"}).draft,undefined);
});
