 const m=sourceModule();m.widgets.chart={id:"chart",name:"Pressure over Assets",type:"ChartXY",config:{objectSetVarId:"notes",chartKind:"line",xProperty:"id",yProperty:"pressure"}};m.sections.root.children.push({kind:"widget",id:"chart"});const mapped={...bindings,fields:{Asset:{...bindings.fields.Asset,pressure:"qty"}}},typed={...target,entities:[{...target.entities[0],fields:[...target.entities[0].fields,{name:"qty",type:"decimal"}]}]},source=JSON.stringify(m),report=compileWorkshopModule(source,"page",mapped,typed);assert.ok(report.draft,JSON.stringify(report.diagnostics));const chart=report.draft.sections.find(s=>s.widget==="record-chart"),v=report.draft.document.variables[chart.collectionVariable];assert.deepEqual(chart.recordChart,{mark:"line",xField:"id",yField:"qty"});assert.deepEqual(report.draft.document.queries[v.source.query].sort,["id"]);assert.equal(chart.measure,undefined);assert.equal(report.source,source);assert.ok(report.diagnostics.some(d=>d.code==="native-record-chart-window"&&!d.blocking));
