test("Spacer imports explicit zero and fractional sizes without coercing invalid or missing source values",()=>{
 const m=sourceModule();m.widgets.blank={id:"blank",name:"Blank region",type:"Spacer",config:{size:16}};m.sections.root.children.push({kind:"widget",id:"blank"});const source=JSON.stringify(m),r=compileWorkshopModule(source,"page",bindings,target);assert.ok(r.draft,JSON.stringify(r.diagnostics));assert.deepEqual(r.draft.sections.find(s=>s.widget==="spacer").spacer,{size:16});assert.equal(r.source,source);assert.equal(compileWorkshopModule(source,"page",bindings,{...target,profile:"platform.page.v2.62"}).draft,undefined);
 for(const size of [undefined,null,0,0.5,16.25,nativeRegistry.layout.maxSize]){const copy=structuredClone(m);if(size===undefined)delete copy.widgets.blank.config.size;else copy.widgets.blank.config.size=size;const result=compileWorkshopModule(JSON.stringify(copy),"page",bindings,target);assert.ok(result.draft,JSON.stringify(result.diagnostics));assert.equal(result.draft.sections.find(s=>s.widget==="spacer").spacer.size,size==null?16:size);}
 for(const change of [m=>m.widgets.blank.config.size=-1,m=>m.widgets.blank.config.size=nativeRegistry.layout.maxSize+0.5,m=>m.widgets.blank.config.size="16",m=>m.widgets.blank.config.size=true,m=>m.widgets.blank.config.variableId="scratch",m=>m.widgets.blank.config.execute="run()"]){const copy=structuredClone(m);change(copy);const result=compileWorkshopModule(JSON.stringify(copy),"page",bindings,target);assert.equal(result.draft,undefined);assert.equal(result.source,JSON.stringify(copy));}
 const nonfinite=source.replace('"size":16','"size":1e999');assert.equal(compileWorkshopModule(nonfinite,"page",bindings,target).draft,undefined);
});
