 for(const map of [{...choices,Maintenance:""},{...choices,Maintenance:"open"},{...choices,extra:"x"},{...choices,Active:"unknown"}])assert.equal(compileWorkshopModule(source,"page",{...bindings2,explorations:{statuses:map}},typed).draft,undefined);
